#include <iostream>
#include <charconv>
#include <string>
bool update(int& value, const std::string& text) {
  if (text.empty() || text.size() > 32) return false;
  int candidate = 0;
  auto [ptr, ec] = std::from_chars(text.data(), text.data() + text.size(), candidate);
  if (ec != std::errc{} || ptr != text.data() + text.size() || candidate < 0 || candidate > 100) return false;
  value = candidate; return true;
}
int main() {
  int value = 17, rejected = 0, count = 0;
  std::string line;
  while (std::getline(std::cin, line)) {
    if (++count > 8) { std::cout << "invalid\n"; return 0; }
    if (!update(value, line)) ++rejected;
  }
  std::cout << "value " << value << " rejected " << rejected << '\n';
}

